UPDATE vm_video_preset
SET is_guard = '0',
    update_time = now(),
    stay_seconds = null
WHERE preset_id != #{presetId}
  AND device_code = #{deviceCode}

UPDATE vm_video_preset
  SET is_guard = '2'
WHERE preset_id = #{presetId}
  AND device_code = #{deviceCode}

UPDATE vm_video_preset
is_algorithm_identify = #{isAlgorithmIdentify}, algorithm_code = #{algorithmCode}, double_img_analysis = #{doubleImgAnalysis},
is_algorithm_identify = #{isAlgorithmIdentify}, algorithm_code = NULL, double_img_analysis = NULL,
preset_id = #{presetId}, preset_name = #{presetName}, preset_code = #{presetCode}, move_speed = #{moveSpeed}, pan = #{pan}, tilt = #{tilt}, zoom = #{zoom}, img_url = #{imgUrl}, device_code = #{deviceCode}, channel_code = #{channelCode}, tenant_id = #{tenantId}, user_code = #{userCode}, create_time = #{createTime}, order_code = #{orderCode}, delete_flag = #{deleteFlag}, is_guard = #{isGuard}, stay_seconds = #{staySeconds}, industry_code = #{industryCode}, app_ver_code = #{appVerCode}, update_time = #{updateTime}, creator = #{creator}, modifier = #{modifier}, modify_time = #{modifyTime}, snapshot_cycle = #{snapshotCycle}, snapshot_day = #{snapshotDay}, snapshot_time = #{snapshotTime}
WHERE preset_id = #{presetId} AND device_code = #{deviceCode}

mapper.select:
SELECT
    preset_name
FROM
    vm_video_preset
WHERE
    tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND device_code = #{deviceCode}
  AND channel_code = #{channelCode}
  AND preset_name LIKE CONCAT(#{presetName}, '%')
  AND delete_flag = 0
ORDER BY
    preset_name DESC

SELECT *
FROM vm_video_preset
WHERE preset_id = #{presetId} AND device_code = #{deviceCode}

SELECT
device_code,channel_code,preset_id,preset_name as "guardName",stay_seconds
from vm_video_preset
where is_guard = '1'
AND preset_id != #{presetId}
AND device_code = #{deviceCode}

SELECT preset_id,preset_name,device_code FROM vm_video_preset WHERE delete_flag = 0 AND (device_code,preset_id) in (
(#{param.deviceCode},#{param.presetId})
)

SELECT dev.channel_code, ( CASE WHEN length( IFNULL( t.channel_name, '' )) = 0 THEN dev.channel_name ELSE t.channel_name END ) AS channelName FROM vm_channel_info_t dev LEFT JOIN ( SELECT DISTINCT tdr.device_code, tdr.channel_code, tdr.channel_name FROM vm_tenant_device_channel_rel_t tdr WHERE ( tdr.device_code, tdr.channel_code, tdr.tenant_id, tdr.industry_code ) IN (
(#{param.deviceCode},#{param.channelCode},#{param.tenantId},#{param.industryCode})
) ) t ON t.device_code = dev.device_code AND t.channel_code = dev.channel_code WHERE dev.delete_flag = '0' AND ( dev.device_code, dev.channel_code ) IN (
(#{param.deviceCode},#{param.channelCode})
)

SELECT device_code, longitude, latitude FROM vm_device_info_t WHERE device_code IN (
#{param.deviceCode}
)

